.page {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px;
  background: #0a0a0a;
  color: #e5e7eb;
  font-family: system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;
}

.card {
  width: 100%;
  max-width: 520px;
  background: #0b1020;
  border: 1px solid #1f2937;
  border-radius: 14px;
  padding: 18px;
  display: grid;
  gap: 14px;
}

.title {
  margin: 0;
  font-size: 18px;
  font-weight: 800;
}

.subtitle {
  margin: 0;
  color: #9ca3af;
  font-size: 12px;
}

.status {
  padding: 10px 12px;
  border: 1px solid #1f2937;
  border-radius: 12px;
  background: #0a0f1e;
  font-weight: 700;
}

.board {
  display: grid;
  grid-template-columns: repeat(3,1fr);
  gap: 10px;
}

.cell {
  aspect-ratio: 1/1;
  border-radius: 14px;
  border: 1px solid rgba(31,41,55,.7);
  background: #0a0f1e;
  color: #e5e7eb;
  font-size: 34px;
  font-weight: 900;
  cursor: pointer;
  display: grid;
  place-items: center;
}

.cell:disabled {
  opacity: .55;
  cursor: not-allowed;
}

.actions {
  display: flex;
  justify-content: flex-end;
}

.ghost {
  background: transparent;
  color: #e5e7eb;
  border: 1px solid #374151;
  border-radius: 12px;
  padding: 10px 14px;
  font-weight: 800;
  cursor: pointer;
}

